ST.xhtml:p:
RTrigger1(CLK := g_biUGearIn OR g_bUGearIn OR bGearIn);
RTrigger2(CLK := g_biUGearOut OR g_bUGearOut OR bGearOut);

IF RTrigger1.Q THEN
  IF Axis_U.NCTOPLC.AxisState <> 8 THEN
    nGearState := 1;
    g_boUGearDone := FALSE;
    g_bUGearDone := FALSE;
    bGearDone := FALSE;
  END_IF;
  bGearIn := FALSE;
  g_bUGearIn := FALSE;
  Ton_StopCoordDiff(IN := FALSE);
END_IF;

IF RTrigger2.Q THEN
  IF Axis_U.NCTOPLC.AxisState = 8 THEN
    nGearState := 2;
    g_boUGearDone := FALSE;
    g_bUGearDone := FALSE;
    bGearDone := FALSE;
  END_IF;
  g_bUGearOut := FALSE;
  bGearOut := FALSE;
END_IF;

CASE nGearState OF
  0:
    nGearState := 0;
  1:
    g_UGearIn.Execute := TRUE;
    g_UGearIn.RatioNumerator := 1.0;
    g_UGearIn.RatioDenominator := 1;
    IF g_UGearIn.InGear THEN
      g_boUGearDone := TRUE;
      g_bUGearDone := TRUE;
      bGearDone := TRUE;
      nGearState := 30;
      bGearCheck := TRUE;
      dCoordDiff := ABS(g_fiUCncCoord - Axis_U.NCTOPLC.ACTPOS);
    END_IF;
    IF g_UGearIn.Error OR g_UGearIn.CommandAborted THEN
      g_UGearIn.Execute := FALSE;
      g_noUGearErrorID := g_UGearIn.ErrorID;
      g_bGearInError := TRUE;
      nGearState := 0;
    END_IF;
  2:
    g_UGearOut.Execute := TRUE;
    g_UGearIn.Execute := FALSE;
    IF g_UGearOut.Done THEN
      g_UGearOut.Execute := FALSE;
      IF Axis_U.NCTOPLC.AxisState = 2 OR Axis_U.NCTOPLC.AxisState = 1 THEN
        nGearState := 0;
      ELSE
        nGearState := 3;
      END_IF;
    END_IF;
    IF g_UGearOut.Error THEN
      g_UGearOut.Execute := FALSE;
      g_bGearInError := TRUE;
      nGearState := 0;
      bGearCheck := FALSE;
    END_IF;
  3:
    g_UMoveStop.Execute := TRUE;
    IF g_UMoveStop.Done THEN
      g_UMoveStop.Execute := FALSE;
      nGearState := 0;
    END_IF;
    IF g_UMoveStop.Commandaborted OR g_UMoveStop.Error THEN
      g_UMoveStop.Execute := FALSE;
      nGearState := 0;
    END_IF;
  30:
    IF Axis_U.NCTOPLC.AxisState = 8 THEN
      IF ABS(ABS(g_fiUCncCoord - Axis_U.NCTOPLC.ACTPOS) - dCoordDiff) > dCoordMaxDiff AND Axis_U.NCTOPLC.AXISSTATE = 8 AND g_nMotionMode<> 5 THEN
          g_bUGearError := TRUE;
      END_IF;
      temp_var := true;    
    ELSE
      temp_var := FALSE;
    END_IF;
    (*U轴静止跟随误差*)
    IF ABS(ABS(g_fiUCncCoord - Axis_U.NCTOPLC.ACTPOS) - dCoordDiff) > dStopCoordMaxDiff AND Axis_U.NCTOPLC.AXISSTATE = 8 AND g_nMotionMode<> 5 AND ABS(g_fUVelocity) < 0.01 THEN
      Ton_StopCoordDiff(IN := TRUE,PT := T#5s);
      IF Ton_StopCoordDiff.Q THEN
        g_bUGearStopError := TRUE;
      END_IF;
    ELSE
      Ton_StopCoordDiff(IN := FALSE);
    END_IF;
END_CASE;
